export function createAvatar(root) {
  if (!root.matches('[data-component="avatar"]') || !root.querySelector('.c-avatar')) throw new Error('createAvatar markup is incomplete.');
  return { destroy() {} };
}
document.querySelectorAll('[data-component="avatar"]').forEach(createAvatar);

