export function createRemovableChips(root) {
  const list=root.querySelector('[data-chip-list]');const status=root.querySelector('[data-chip-status]');
  if(!(list instanceof HTMLElement)||!(status instanceof HTMLElement))throw new Error('Removable chip markup is incomplete.');
  const remove=(button)=>{const chip=button.closest('[data-chip]');if(!chip)return;const label=chip.querySelector('[data-chip-label]')?.textContent.trim()||'Item';chip.remove();status.textContent=`${label} removed.`;root.dispatchEvent(new CustomEvent('chip:remove',{detail:{label}}));};
  const click=(event)=>{const button=event.target.closest('[data-chip-remove]');if(button&&root.contains(button))remove(button);};
  root.addEventListener('click',click);
  return{destroy(){root.removeEventListener('click',click);}};
}
document.querySelectorAll('[data-component="removable-chips"]').forEach(createRemovableChips);

