export function createTooltip(root) {
  const trigger=root.querySelector('[data-tooltip-trigger]');const tooltip=root.querySelector('[role="tooltip"]');
  if(!(trigger instanceof HTMLElement)||!(tooltip instanceof HTMLElement))throw new Error('Tooltip markup is incomplete.');
  let hovered=false;let focused=false;
  const sync=()=>{tooltip.hidden=!(hovered||focused);};
  const enter=()=>{hovered=true;sync();};const leave=()=>{hovered=false;sync();};const focus=()=>{focused=true;sync();};const blur=()=>{focused=false;sync();};
  const keydown=(event)=>{if(event.key==='Escape'){hovered=false;focused=false;tooltip.hidden=true;trigger.focus();}};
  trigger.addEventListener('pointerenter',enter);trigger.addEventListener('pointerleave',leave);trigger.addEventListener('focus',focus);trigger.addEventListener('blur',blur);trigger.addEventListener('keydown',keydown);
  return{show(){focused=true;sync();},hide(){hovered=false;focused=false;sync();},destroy(){trigger.removeEventListener('pointerenter',enter);trigger.removeEventListener('pointerleave',leave);trigger.removeEventListener('focus',focus);trigger.removeEventListener('blur',blur);trigger.removeEventListener('keydown',keydown);}};
}
document.querySelectorAll('[data-component="tooltip"]').forEach(createTooltip);
